typeProperties.script:
section Section1;
shared SupplierDeliveries = let AdfDoc = AzureStorage.DataLakeContents("https://stnfmfgdev.dfs.core.windows.net/landing/supplier_deliveries/powerquery_input/supplier_deliveries_current.csv"), Csv = Csv.Document(AdfDoc, [Delimiter = ",", Encoding = TextEncoding.Utf8, QuoteStyle = QuoteStyle.Csv]), PromotedHeaders = Table.PromoteHeaders(Csv, [PromoteAllScalars = true]) in PromotedHeaders;
shared UserQuery = let
    Source = SupplierDeliveries,
    // 1. trim stray spaces on every text key
    Trimmed = Table.TransformColumns(Source, {{"delivery_id", Text.Trim}, {"supplier_id", Text.Trim}, {"supplier_name", Text.Trim}, {"material_code", Text.Trim}, {"plant_id", Text.Trim}, {"lot_number", Text.Trim}}),
    // 2. standardise codes to upper case, names to proper case
    Uppercased = Table.TransformColumns(Trimmed, {{"delivery_id", Text.Upper}, {"supplier_id", Text.Upper}, {"material_code", Text.Upper}, {"plant_id", Text.Upper}, {"lot_number", Text.Upper}}),
    ProperNames = Table.TransformColumns(Uppercased, {{"supplier_name", Text.Proper}}),
    // 3. data types
    Typed = Table.TransformColumnTypes(ProperNames, {{"delivery_date", type date}, {"delivered_qty", Int64.Type}, {"rejected_qty", Int64.Type}}),
    // 4. business rules: key present, quantities valid
    HasKey = Table.SelectRows(Typed, each [delivery_id] <> null and [delivery_id] <> ""),
    ValidQty = Table.SelectRows(HasKey, each [delivered_qty] > 0 and [rejected_qty] >= 0 and [rejected_qty] <= [delivered_qty]),
    // 5. suppliers re-send lines: one row per delivery_id
    Deduped = Table.Distinct(ValidQty, {"delivery_id"}),
    // 6. derived measure
    WithAccepted = Table.AddColumn(Deduped, "accepted_qty", each [delivered_qty] - [rejected_qty], Int64.Type)
in
    WithAccepted;
